import { useEffect, useRef, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { labExperiments, type LabExperiment } from './data/lab'
import { workProjects, type WorkProject } from './data/work'
import { contact } from './data/contact'
import { CaseMedia, CaseMediaPair } from './components/work/CaseMedia'
import './styles.css'

type ResponseMode = 'focus' | 'recompose' | 'connect' | 'divide' | 'sequence'
type Page = 'home' | 'about' | 'work' | 'workCaseStudy' | 'lab' | 'labExperiment'
type PortfolioResponse = { terms: string[]; mode: ResponseMode; targets: string[]; route?: Page; routeTarget?: string; classification: { intent: string; evidence: string; representation: string } }

const responses: PortfolioResponse[] = [
  { terms: ['what is yousewire', 'tell me about yousewire', 'malik do on yousewire', 'design fintech', 'personal and business differ', 'yousewire verification', 'transaction tiers', 'business payments', 'roles and permissions', 'approval workflows', 'design payroll', 'work with developers', 'consistency without uniformity'], mode: 'connect', targets: ['yousewire-contexts'], route: 'workCaseStudy', routeTarget: 'yousewire-contexts', classification: { intent: 'YOUSEWIRE', evidence: 'CASE 003', representation: 'CONNECT' } },
  { terms: ['what is hanya', 'tell me about hanya', 'hanya healthcare', 'ai in healthcare', 'design hanya', 'hanya handle safety', 'hanya diagnose', 'ai do in hanya', 'deterministic logic', 'test hanya', 'provider discovery'], mode: 'connect', targets: ['hanya-navigation-gap'], route: 'workCaseStudy', routeTarget: 'hanya-navigation-gap', classification: { intent: 'HANYA', evidence: 'CASE 002', representation: 'CONNECT' } },
  { terms: ['what is prima', 'prima', 'ai product work', 'ai authority', 'design for trust', 'handle uncertainty', 'systems thinking example', 'ai explainability'], mode: 'connect', targets: ['prima-premise'], route: 'workCaseStudy', routeTarget: 'prima-premise', classification: { intent: 'PRIMA', evidence: 'CASE 001', representation: 'CONNECT' } },
  { terms: ['what has malik worked on', 'show me malik work', 'show me his work', 'what products has malik designed', 'show me his product work'], mode: 'focus', targets: ['work'], route: 'work', classification: { intent: 'WORK', evidence: 'WORK INDEX', representation: 'FOCUS' } },
  { terms: ['what is the lab', "what's in the lab", 'whats in the lab', 'malik experimenting', 'malik is experimenting', 'his experiments', 'show me his experiments', 'the lab', 'ai experiments', 'what does malik build with ai', 'what do you build with ai'], mode: 'focus', targets: ['lab'], route: 'lab', classification: { intent: 'LAB', evidence: 'LAB', representation: 'FOCUS' } },
  { terms: ['how did malik get into product design', 'how did you get into product design', 'background'], mode: 'sequence', targets: ['about-background'], route: 'about', routeTarget: 'about-background', classification: { intent: 'BACKGROUND', evidence: 'ABOUT', representation: 'SEQUENCE' } },
  { terms: ['how does malik work', 'how do you work', 'what tools does malik use', 'what tools do you use'], mode: 'connect', targets: ['about-working-system'], route: 'about', routeTarget: 'about-working-system', classification: { intent: 'WORKING SYSTEM', evidence: 'ABOUT', representation: 'CONNECT' } },
  { terms: ['what does malik care about', 'what do you care about'], mode: 'connect', targets: ['about-principles'], route: 'about', routeTarget: 'about-principles', classification: { intent: 'PRINCIPLES', evidence: 'ABOUT', representation: 'CONNECT' } },
  { terms: ['outside work', 'outside of work'], mode: 'focus', targets: ['about-offline'], route: 'about', routeTarget: 'about-offline', classification: { intent: 'OFFLINE', evidence: 'ABOUT', representation: 'FOCUS' } },
  { terms: ['tell me about malik', 'about malik', 'who is malik'], mode: 'recompose', targets: ['about'], route: 'about', classification: { intent: 'PROFILE', evidence: 'ABOUT', representation: 'RECOMPOSE' } },
  { terms: ['what does malik do', 'what do you do'], mode: 'recompose', targets: ['hero', 'capabilities'], classification: { intent: 'ROLE', evidence: 'CAPABILITIES', representation: 'RECOMPOSE' } },
  { terms: ['what ai tools', 'ai tools', 'ai agents', 'ai workflow', 'how does malik use ai', 'how do you use ai'], mode: 'connect', targets: ['capabilities'], classification: { intent: 'WORKFLOW', evidence: 'AI WORKFLOW', representation: 'CONNECT' } },
  { terms: ['how does malik think about ai', 'think about ai', 'ai', 'intelligence'], mode: 'connect', targets: ['thinking'], classification: { intent: 'PHILOSOPHY', evidence: 'THINKING', representation: 'CONNECT' } },
  { terms: ['design or code', 'design and code', 'frontend', 'implementation'], mode: 'divide', targets: ['capabilities'], classification: { intent: 'CAPABILITIES', evidence: 'DESIGN + BUILD', representation: 'DIVIDE' } },
  { terms: ['how does malik approach complexity', 'complexity', 'systems thinking', 'systems'], mode: 'connect', targets: ['thinking'], classification: { intent: 'APPROACH', evidence: 'THINKING', representation: 'CONNECT' } },
  { terms: ['why malik', 'why should', 'experience'], mode: 'sequence', targets: ['experience'], classification: { intent: 'EVOLUTION', evidence: 'EXPERIENCE', representation: 'SEQUENCE' } },
  { terms: ['contact', 'contact malik', 'email', 'linkedin', 'availability', 'available', 'talk'], mode: 'focus', targets: ['contact'], route: 'home', routeTarget: 'contact', classification: { intent: 'CONTACT', evidence: 'CONTACT', representation: 'FOCUS' } }
]

const principles = [
  ['01', 'MAKE INTELLIGENCE LEGIBLE.', 'People should understand what a system knows, what it does not, and why it is responding.', 'intelligence'],
  ['02', 'DESIGN UNCERTAINTY.', 'Intelligent products do not always have definitive answers. Design what happens when confidence is low.', 'uncertainty'],
  ['03', 'CONTEXT BEFORE AUTOMATION.', 'Automating the wrong interpretation only makes the wrong outcome faster.', 'context'],
  ['04', 'EARN TRUST BEFORE ASKING FOR ACTION.', 'Explain enough for people to make informed decisions.', 'trust'],
  ['05', 'PROTOTYPE THE SYSTEM, NOT ONLY THE SCREEN.', 'Interaction reveals assumptions static layouts hide.', 'prototype'],
  ['06', 'HUMANS STILL DECIDE.', 'AI can assist judgement. It should not quietly replace it.', 'human']
]
const stages = [['2018', 'VISUAL DESIGN', 'COMMUNICATION'], ['2022', 'PRODUCT DESIGN', 'BEHAVIOUR'], ['2023', 'PRODUCT SYSTEMS', 'RELATIONSHIPS'], ['2024', 'DESIGN LEADERSHIP', 'SCALE'], ['2025', 'DESIGN + BUILD', 'IMPLEMENTATION'], ['2026', 'AI PRODUCT DESIGN', 'INTELLIGENT BEHAVIOUR']]
const routeFromPath = () => {
  const segments = window.location.pathname.split('/').filter(Boolean)
  if (segments[0] === 'about') return { page: 'about' as Page }
  if (segments[0] === 'work' && segments[1]) return { page: 'workCaseStudy' as Page, slug: segments[1] }
  if (segments[0] === 'work') return { page: 'work' as Page }
  if (segments[0] === 'lab' && segments[1]) return { page: 'labExperiment' as Page, slug: segments[1] }
  if (segments[0] === 'lab') return { page: 'lab' as Page }
  return { page: 'home' as Page }
}

function App() {
  const [route, setRoute] = useState(routeFromPath)
  const page = route.page
  const [machineOpen, setMachineOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [interpreting, setInterpreting] = useState(false)
  const [response, setResponse] = useState<PortfolioResponse | null>(null)
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [showBackToTop, setShowBackToTop] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const mobileMenuRef = useRef<HTMLDivElement>(null)
  const mobileMenuTriggerRef = useRef<HTMLButtonElement>(null)
  const reducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches
  const navigate = (next: Page, target?: string, slug?: string) => {
    const path = next === 'home' ? '/' : next === 'workCaseStudy' ? `/work/${slug}` : next === 'labExperiment' ? `/lab/${slug}` : `/${next}`
    window.history.pushState(null, '', path)
    setRoute({ page: next, slug }); setResponse(null)
    window.setTimeout(() => {
      const destination = document.getElementById(target ?? 'top')
      if (destination) destination.scrollIntoView({ behavior: reducedMotion() ? 'auto' : 'smooth', block: 'start' })
      else window.scrollTo({ top: 0, behavior: reducedMotion() ? 'auto' : 'smooth' })
    }, 30)
  }
  const openAsk = () => { setMachineOpen(true); setInterpreting(false); setQuery('') }
  const closeMobileMenu = () => { setMobileMenuOpen(false); window.setTimeout(() => mobileMenuTriggerRef.current?.focus(), 0) }
  const restore = () => { setResponse(null); window.history.replaceState(null, '', page === 'home' ? '/' : `/${page}`) }
  const submit = (value: string) => {
    const match = responses.find(item => item.terms.some(term => value.toLowerCase().includes(term)))
    if (!match) return
    setQuery(value); setInterpreting(true)
    window.setTimeout(() => {
      setInterpreting(false); setMachineOpen(false)
      if (match.route) { navigate(match.route, match.routeTarget, match.classification.intent === 'PRIMA' ? 'prima' : match.classification.intent === 'HANYA' ? 'hanya' : match.classification.intent === 'YOUSEWIRE' ? 'yousewire' : undefined); return }
      setResponse(match); window.history.replaceState({ ask: match.mode }, '', `#${match.targets[0]}`)
      window.setTimeout(() => document.getElementById(match.targets[0])?.scrollIntoView({ behavior: reducedMotion() ? 'auto' : 'smooth', block: 'start' }), 40)
    }, reducedMotion() ? 0 : 560)
  }
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setMobileMenuOpen(false); openAsk() }
      if (event.key === 'Escape') { if (mobileMenuOpen) closeMobileMenu(); else if (machineOpen) setMachineOpen(false); else if (response) restore() }
    }
    const onPopState = () => { setRoute(routeFromPath()); setResponse(null) }
    window.addEventListener('keydown', onKey); window.addEventListener('popstate', onPopState)
    return () => { window.removeEventListener('keydown', onKey); window.removeEventListener('popstate', onPopState) }
  }, [machineOpen, mobileMenuOpen, response, page])
  useEffect(() => { if (machineOpen) window.setTimeout(() => inputRef.current?.focus(), 150) }, [machineOpen])
  useEffect(() => {
    const updateBackToTop = () => {
      const pastThreshold = window.scrollY > window.innerHeight * .5
      const nearFooter = window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 130
      setShowBackToTop(pastThreshold && !nearFooter)
    }
    updateBackToTop()
    window.addEventListener('scroll', updateBackToTop, { passive: true })
    window.addEventListener('resize', updateBackToTop)
    return () => { window.removeEventListener('scroll', updateBackToTop); window.removeEventListener('resize', updateBackToTop) }
  }, [])
  useEffect(() => {
    if (!mobileMenuOpen) return
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    window.setTimeout(() => mobileMenuRef.current?.querySelector<HTMLButtonElement>('.mobile-menu-link')?.focus(), 100)
    return () => { document.body.style.overflow = previousOverflow }
  }, [mobileMenuOpen])
  const handleIntelligentMove = (event: React.PointerEvent<HTMLSpanElement>) => {
    if (reducedMotion() || event.pointerType !== 'mouse') return
    const speed = Math.min(1, (Math.abs(event.movementX) + Math.abs(event.movementY)) / 26)
    event.currentTarget.style.setProperty('--tilt', `${(event.clientX % 15 - 7) * speed * .16}deg`); event.currentTarget.style.setProperty('--stretch', `${1 + speed * .035}`)
  }
  const movePromptFocus = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowDown', 'ArrowUp', 'ArrowLeft', 'ArrowRight'].includes(event.key)) return
    const prompts = [...event.currentTarget.querySelectorAll('button')]; const current = prompts.indexOf(document.activeElement as HTMLButtonElement)
    if (current < 0) return
    event.preventDefault(); const offset = event.key === 'ArrowDown' || event.key === 'ArrowRight' ? 1 : -1; prompts[(current + offset + prompts.length) % prompts.length]?.focus()
  }
  const trapMobileMenuFocus = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== 'Tab') return
    const focusable = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not([disabled])')]
    const current = focusable.indexOf(document.activeElement as HTMLButtonElement)
    if (current < 0) return
    event.preventDefault()
    const next = event.shiftKey ? (current - 1 + focusable.length) % focusable.length : (current + 1) % focusable.length
    focusable[next]?.focus()
  }
  const active = response?.mode
  const backToTop = () => window.scrollTo({ top: 0, behavior: reducedMotion() ? 'auto' : 'smooth' })
  return <main className={`${page !== 'home' ? `page-${page}` : ''} ${active ? `orchestrating mode-${active} response-${response?.classification.intent.toLowerCase()}` : ''}`}>
    {response && <button className="return" onClick={restore}>M<span>/</span> RETURN</button>}
    {showBackToTop && !mobileMenuOpen && !machineOpen && !response && <button className="back-to-top" onClick={backToTop} aria-label="Back to top">M/ ↑ TOP</button>}
    <header className="nav"><button className="mark brand-signature" onClick={() => navigate('home')} aria-label="Temitayo Lawal Malik - Home">M<span className="mark-slash">/</span><span className="brand-name">TEMITAYO LAWAL MALIK</span></button><span className="year">2026</span><nav aria-label="Primary navigation"><button onClick={() => navigate('work')}>WORK</button><button onClick={() => navigate('about')}>ABOUT</button><button onClick={() => navigate('lab')}>LAB</button><button onClick={openAsk}>ASK MALIK <i>↗</i></button></nav><button className="mobile-menu-trigger" ref={mobileMenuTriggerRef} onClick={() => setMobileMenuOpen(true)} aria-expanded={mobileMenuOpen} aria-controls="mobile-navigation">MENU +</button></header>
    {page === 'home' && <><section className="hero" id="hero"><div className="hero-title" aria-label="I design intelligent products for human decisions"><span>I DESIGN</span><span className="intelligent" onPointerMove={handleIntelligentMove}>INTELLIGENT</span><span>PRODUCTS</span><span>FOR HUMAN <em>decisions.</em></span></div><div className="role-response"><div>PRODUCT DESIGNER</div><span>AI / UX / SYSTEMS</span><p>I work where product thinking, interaction and implementation meet.</p></div><div className="hero-meta"><span>PRODUCT DESIGNER<br />AI / UX / SYSTEMS</span><span>LAGOS, NG<br />GLOBAL / REMOTE</span></div><button className="ask-entry" onClick={openAsk}><b>●</b> ASK ME SOMETHING</button><p className="annotation">because someone still has to make one.</p></section><SelectedWork onProjectOpen={slug => navigate('workCaseStudy', undefined, slug)} onAllWork={() => navigate('work')} /><HomeSections submit={submit} /></>}
    {page === 'about' && <About />}
    {page === 'work' && <WorkIndex onProjectOpen={slug => navigate('workCaseStudy', undefined, slug)} />}
    {page === 'workCaseStudy' && <WorkPreparation project={workProjects.find(project => project.slug === route.slug)} onBack={() => navigate('work')} />}
    {page === 'lab' && <Lab onExperimentOpen={slug => navigate('labExperiment', undefined, slug)} />}
    {page === 'labExperiment' && <LabExperimentPage experiment={labExperiments.find(experiment => experiment.slug === route.slug)} onBack={() => navigate('lab')} />}
    {page !== 'home' && <GlobalFooter />}
    {mobileMenuOpen && <div className="mobile-menu" ref={mobileMenuRef} id="mobile-navigation" role="dialog" aria-modal="true" aria-label="Mobile navigation" onKeyDown={trapMobileMenuFocus}><div className="mobile-menu-head"><button className="mark brand-signature" onClick={() => { closeMobileMenu(); navigate('home') }} aria-label="Temitayo Lawal Malik - Home">M<span className="mark-slash">/</span><span className="brand-name">TEMITAYO LAWAL MALIK</span></button><button className="mobile-menu-close" onClick={closeMobileMenu}>CLOSE ×</button></div><div className="mobile-menu-links"><button className="mobile-menu-link" onClick={() => { closeMobileMenu(); navigate('work') }}>WORK</button><button className="mobile-menu-link" onClick={() => { closeMobileMenu(); navigate('about') }}>ABOUT</button><button className="mobile-menu-link" onClick={() => { closeMobileMenu(); navigate('lab') }}>LAB</button><button className="mobile-menu-link" onClick={() => { closeMobileMenu(); openAsk() }}>ASK MALIK <span>↗</span></button></div><div className="mobile-menu-meta">PRODUCT DESIGNER<br />AI / UX / SYSTEMS<br /><br />LAGOS / GLOBAL<br />2026</div></div>}
    {machineOpen && <section className="machine" aria-label="Ask Malik"><div className="machine-head"><button className="mark" onClick={() => setMachineOpen(false)} aria-label="Return to portfolio">M<span className="mark-slash">/</span></button><span>MACHINE</span><span><b>●</b> ACTIVE</span><button className="close" onClick={() => setMachineOpen(false)}>ESC / CLOSE</button></div>{!interpreting ? <div className="ask-stage"><h2>WHAT WOULD YOU<br />LIKE TO KNOW?</h2><form onSubmit={event => { event.preventDefault(); submit(query) }}><label htmlFor="ask-input">&gt; ASK A QUESTION</label><input ref={inputRef} id="ask-input" value={query} onChange={event => setQuery(event.target.value)} placeholder="TYPE HERE" /></form><div className="prompts" onKeyDown={movePromptFocus}>{['WHAT DOES MALIK DO?', 'HOW DOES HE THINK ABOUT AI?', 'DESIGN OR CODE?', 'WHAT AI TOOLS DOES MALIK USE?', 'WHAT IS THE LAB?', 'WHY MALIK?'].map(prompt => <button key={prompt} onClick={() => submit(prompt)}>{prompt}<span>↗</span></button>)}</div></div> : <div className="classify"><strong>M/ INTERPRETING</strong><div><span>INTENT</span>{responses.find(item => item.terms.some(term => query.toLowerCase().includes(term)))?.classification.intent}</div><div><span>CONTEXT</span>{responses.find(item => item.terms.some(term => query.toLowerCase().includes(term)))?.classification.evidence}</div><div><span>REPRESENTATION</span>{responses.find(item => item.terms.some(term => query.toLowerCase().includes(term)))?.classification.representation}</div><div><span>CONFIDENCE</span>HIGH</div></div>}</section>}
  </main>
}

function SelectedWork({ onProjectOpen, onAllWork }: { onProjectOpen: (slug: string) => void; onAllWork: () => void }) { const selected = workProjects.filter(project => project.featured); return <section className="selected-work" id="selected-work"><div className="section-label">M/ SELECTED WORK <span>{String(selected.length).padStart(2, '0')} PROJECTS</span></div><h2>SELECTED<br />WORK.</h2><div className="selected-work-list">{selected.map(project => <article key={project.slug} className={project.hasCaseStudy ? 'is-ready' : ''}><div className="selected-media" aria-hidden="true"><span>M/ MEDIA {project.index}</span><small>PROJECT CAPTURE<br />PENDING</small></div><div className="selected-project-meta"><span>{project.index} /</span>{project.category && <small>{project.category}</small>}</div><h3>{project.name}</h3>{project.summary && <p>{project.summary}</p>}{project.hasCaseStudy ? <button onClick={() => onProjectOpen(project.slug)}>VIEW CASE <span>↗</span></button> : <span className="case-pending">CASE IN PREPARATION</span>}</article>)}</div><button className="all-work-link" onClick={onAllWork}><span>M/ WORK INDEX<br />ALL PROJECTS</span>VIEW ALL WORK <b>↗</b></button></section> }

function HomeSections({ submit }: { submit: (question: string) => void }) { return <><section className="thinking section" id="thinking"><div className="section-label">M/ THINKING <span>02</span></div><h2>Systems need<br /><em>human</em> judgement.</h2><div className="connect-labels"><span>INTELLIGENCE</span><span>CONTEXT</span><span>UNCERTAINTY</span><span>TRUST</span><span>HUMAN JUDGEMENT</span></div><div className="principles">{principles.map(([number, title, copy, key]) => <article id={`principle-${key}`} key={number}><span>{number}</span><h3>{title}</h3><p>{copy}</p></article>)}</div></section><section className="capabilities section" id="capabilities"><div className="section-label">M/ CONNECT <span>03</span></div><h2>Thinking in<br />relationships.</h2><div className="divide-response"><div><strong>DESIGN</strong><span>PRODUCT THINKING</span><span>UX</span><span>INTERACTION</span><span>VISUAL SYSTEMS</span><span>DESIGN SYSTEMS</span></div><b>/</b><div><strong>CODE</strong><span>HTML</span><span>CSS</span></div><p>PROTOTYPING<br /><b>DESIGN → BUILD</b><em>I use HTML and CSS to get closer to the thing people actually experience.</em></p></div><div className="workflow-response"><strong>AI WORKFLOW</strong><div><span>THINK</span><b>CHATGPT / OPENAI / CLAUDE</b></div><i>↓</i><div><span>DESIGN</span><b>FIGMA / FIGMA MAKE</b></div><i>↓</i><div><span>PROTOTYPE</span><b>LOVABLE</b></div><i>↓</i><div><span>BUILD / ITERATE</span><b>CLAUDE / OPENCODE</b></div><p>AI PRODUCT DESIGN</p><em>I use AI across the process, not as a substitute for the process.</em></div><div className="map"><div id="capability-product">AI PRODUCT DESIGN</div><span>│</span><div>├── PRODUCT THINKING</div><div id="capability-interaction">├── INTERACTION DESIGN</div><div id="capability-prototyping">├── PROTOTYPING</div><div>├── TRUST &amp; SAFETY</div><div id="capability-systems">├── SYSTEMS THINKING</div><button id="capability-ai-workflow" className="workflow-node" onClick={() => submit('What AI tools does Malik use?')}>└── AI WORKFLOW</button></div></section><section className="experience section" id="experience"><div className="section-label">M/ EVOLUTION <span>04</span></div><h2>Learning in<br /><em>public.</em></h2><div className="timeline">{stages.map(([year, role, addition]) => <div id={`stage-${year}`} key={year}><span>{year}</span><b>{role}</b><small>{addition}</small><i>+</i></div>)}</div><p className="sequence-note">The tools changed. The problem stayed the same: making complicated things easier to understand and use.</p><p className="experience-note">A practice evolving from visual craft toward products, systems and intelligent interfaces.</p></section><Contact /></> }

function About() {
  const [openProcess, setOpenProcess] = useState('UNDERSTAND')
  const [openPrinciple, setOpenPrinciple] = useState('TRUST & EXPLAINABILITY')
  const process = [['UNDERSTAND', 'Map the problem, users, context and constraints.'], ['SIMPLIFY', 'Reduce complexity without removing what matters.'], ['PROTOTYPE', 'Make assumptions tangible enough to test.'], ['EVALUATE', 'Observe what works, what fails and what remains unclear.'], ['REFINE', 'Improve behaviour, clarity and implementation.'], ['SHIP', 'Move the work into reality and learn from use.']]
  const cares = [['TRUST & EXPLAINABILITY', 'Making enough of a system visible for people to make informed decisions.'], ['SYSTEMS THINKING', 'Looking for relationships, constraints and the effects that exist beyond one screen.'], ['HUMAN-CENTERED AI', 'Exploring intelligence that supports judgement rather than quietly replacing it.'], ['PRIVACY & IDENTITY', 'Areas I care about when products ask people to share who they are.'], ['FINANCIAL INCLUSION', 'An area I care about where clarity and access can materially matter.'], ['DEVELOPER EXPERIENCE', 'An area I explore through the relationship between design and implementation.']]
  return <section className="about-v2" id="about"><div className="about-hero"><div className="section-label">M/ ABOUT <span>01</span></div><h1>DESIGNING<br />TECHNOLOGY<br />THAT FEELS MORE<br /><em>human.</em></h1><p>I’m a Product Designer working across product thinking, interaction, visual systems, prototyping and increasingly AI product design.</p><div className="about-machine"><span>M/ INTERPRETATION</span><p>VISUAL THINKER<br />PRODUCT DESIGNER<br />SYSTEMS ORIENTED<br />DESIGN + BUILD<br />AI PRODUCT DESIGN</p></div></div><section className="about-background" id="about-background"><div className="section-label">M/ BACKGROUND <span>02</span></div><h2>THE PRACTICE<br /><em>EXPANDED.</em></h2><p className="about-human-note">I didn’t really leave visual design behind. I kept adding new questions to it.</p><div className="background-sequence">{[['VISUAL / BRAND DESIGN', 'COMMUNICATION / COMPOSITION / IDENTITY'], ['PRODUCT DESIGN', 'BEHAVIOUR / USABILITY / USER PROBLEMS'], ['PRODUCT SYSTEMS', 'RELATIONSHIPS / SCALE / COMPLEXITY'], ['DESIGN LEADERSHIP', 'CRITIQUE / COLLABORATION / DECISION-MAKING'], ['DESIGN + BUILD', 'IMPLEMENTATION / FEASIBILITY / ITERATION'], ['AI PRODUCT DESIGN', 'INTELLIGENT BEHAVIOUR / TRUST / UNCERTAINTY / HUMAN JUDGEMENT']].map(([stage, addition], index) => <div key={stage}><span>{String(index + 1).padStart(2, '0')}</span><b>{stage}</b><small>{addition}</small></div>)}</div></section><section className="about-process" id="about-process"><div className="section-label">M/ PROCESS <span>03</span></div><h2>HOW I<br /><em>THINK.</em></h2><div className="process-sequence">{process.map(([stage, detail], index) => <button className={openProcess === stage ? 'is-active' : ''} onClick={() => setOpenProcess(stage)} key={stage}><span>{String(index + 1).padStart(2, '0')}</span><b>{stage}</b><p>{openProcess === stage ? detail : ''}</p></button>)}</div></section><section className="about-principles" id="about-principles"><div className="section-label">M/ PRINCIPLES <span>04</span></div><h2>WHAT I<br /><em>CARE ABOUT.</em></h2><div className="care-list">{cares.map(([title, detail], index) => <button className={openPrinciple === title ? 'is-active' : ''} onClick={() => setOpenPrinciple(title)} key={title}><span>{String(index + 1).padStart(2, '0')}</span><b>{title}</b><p>{openPrinciple === title ? detail : ''}</p></button>)}</div></section><section className="about-working" id="about-working-system"><div className="section-label">M/ WORKING SYSTEM <span>05</span></div><h2>HOW I<br /><em>WORK.</em></h2><div className="working-roles"><div><span>DESIGN</span><p>FIGMA<br />FIGMA MAKE</p></div><div><span>PROTOTYPE</span><p>FIGMA<br />LOVABLE</p></div><div><span>BUILD</span><p>HTML<br />CSS<br />FRAMER<br />CLAUDE<br />OPENCODE</p></div><div><span>THINK / COLLABORATE</span><p>CHATGPT<br />CLAUDE<br />MIRO<br />NOTION</p></div></div><p className="about-human-note">Different tools, different jobs. The design decisions are still mine.</p></section><section className="about-experience" id="about-experience"><div className="section-label">M/ EXPERIENCE <span>06</span></div><h2>SELECTED<br /><em>EXPERIENCE.</em></h2><div className="experience-empty"><span>PROFESSIONAL CONTEXT</span><p>Verified role and organization details are not indexed here yet.</p></div></section><section className="about-offline" id="about-offline"><div className="section-label">M/ OFFLINE <span>07</span></div><h2>WHEN I’M NOT<br /><em>DESIGNING...</em></h2><p>Personal notes are not indexed here yet.</p></section></section>
}

function WorkIndex({ onProjectOpen }: { onProjectOpen: (slug: string) => void }) { return <section className="work-page" id="work"><div className="section-label">M/ WORK <span>INDEX</span></div><h1>SELECTED<br />PRODUCT<br />WORK.</h1><p className="work-intro">A selection of products, systems and experiences I've designed across AI, fintech and digital platforms.</p><div className="work-index">{workProjects.map(project => <article key={project.slug}><button onClick={() => onProjectOpen(project.slug)} aria-label={`Open ${project.name} ${project.hasCaseStudy ? 'case study' : 'case study preparation'}`}><span>{project.index} /</span><div className="work-media" aria-hidden="true">MEDIA / IN PREPARATION</div><h2>{project.name}</h2><small>{project.status}</small></button></article>)}</div></section> }

function WorkPreparation({ project, onBack }: { project?: WorkProject; onBack: () => void }) {
  if (project?.slug === 'prima') return <PrimaCase onBack={onBack} />
  if (project?.slug === 'hanya') return <HanyaCase onBack={onBack} />
  if (project?.slug === 'yousewire') return <YousewireCase onBack={onBack} />
  return <section className="work-preparation" id="top"><div className="section-label">M/ WORK <span>CASE STUDY</span></div><h1>{project?.name ?? 'PROJECT'}<br /><em>IN PREPARATION.</em></h1><p>This case study is being prepared.</p><button onClick={onBack}>← BACK TO WORK</button></section>
}

function YousewireCase({ onBack }: { onBack: () => void }) {
  const [activeAct, setActiveAct] = useState(1)
  useEffect(() => { const acts = [...document.querySelectorAll<HTMLElement>('.yousewire-case .case-act')]; const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) setActiveAct(Number((entry.target as HTMLElement).dataset.act ?? 1)) }), { threshold: .35 }); acts.forEach(act => observer.observe(act)); return () => observer.disconnect() }, [])
  return <article className="yousewire-case" id="top"><div className="case-progress" aria-label={`Case study progress: act ${activeAct} of 8`}>M/ CASE 003 <span>{String(activeAct).padStart(2, '0')} / 08</span></div><header className="yousewire-hero"><div className="section-label">M/ CASE 003 <span>YOUSEWIRE</span></div><h1>ONE FINANCIAL<br />ECOSYSTEM.<br />TWO VERY<br />DIFFERENT CONTEXTS.</h1><p>A cross-border financial platform designed to help individuals and businesses hold, move, receive, convert, and manage money across currencies and payment networks.</p><dl className="case-metadata"><div><dt>ROLE</dt><dd>Product Designer</dd></div><div><dt>PLATFORM</dt><dd>Responsive Web Application</dd></div><div><dt>DESIGN</dt><dd>Figma</dd></div><div><dt>COLLABORATION</dt><dd>Product/Project Managers<br />Developers<br />Stakeholders</dd></div><div><dt>LIVE PRODUCT</dt><dd>Yousewire Console</dd></div></dl><CaseMedia index="01" title="YOUSEWIRE CONSOLE / PRIMARY PRODUCT VIEW" className="case-hero-media" /></header>
    <CaseAct number="01" title="ONE SYSTEM, TWO CONTEXTS" id="yousewire-contexts"><CaseStatement>CROSS-BORDER FINANCE<br />BECOMES COMPLEX<br /><em>VERY QUICKLY.</em></CaseStatement><div className="yousewire-contexts"><section><span>PERSONAL</span><p>Open a wallet<br />Receive money<br />Convert funds<br />Send money<br />Understand transactions</p></section><section><span>BUSINESS</span><p>Manage funds<br />Pay people<br />Control access<br />Approve transactions<br />Track operations<br />Manage compliance<br />Reconcile activity</p></section></div><p className="case-thesis">ONE YOUSEWIRE ACCOUNT.<br />TWO CLEARLY SEGMENTED FINANCIAL CONTEXTS.</p><p className="case-body">Personal and Business share one product ecosystem while navigation, data and responsibilities remain segmented.</p><CaseMediaPair left={{ index:'02', title:'PERSONAL DASHBOARD' }} right={{ index:'03', title:'BUSINESS DASHBOARD' }} /></CaseAct>
    <CaseAct number="02" title="DESIGNING THE COMPLEXITY BOUNDARY" id="yousewire-boundary" dark><CaseStatement>CONSISTENCY<br />WITHOUT<br /><em>UNIFORMITY.</em></CaseStatement><div className="yousewire-boundary"><span>SHARED SYSTEM</span><p>TYPOGRAPHY / COLOR SYSTEM / COMPONENTS / INTERACTION CONVENTIONS / FEEDBACK PATTERNS / NAVIGATION PRINCIPLES</p><i>↓</i><div><section><b>PERSONAL</b>LOWER DENSITY<br />SHALLOWER NAVIGATION<br />DIRECT ACTIONS<br />EVERYDAY MONEY<br />SIMPLER WORKFLOWS</section><section><b>BUSINESS</b>HIGHER DENSITY<br />DEEPER NAVIGATION<br />OPERATIONAL CONTROLS<br />ADMINISTRATION<br />MULTI-STEP WORKFLOWS</section></div></div><p className="case-thesis">THE SYSTEM STAYS CONSISTENT.<br />THE COMPLEXITY CHANGES WITH THE CONTEXT.</p></CaseAct>
    <CaseAct number="03" title="MONEY ACROSS BORDERS" id="yousewire-money"><CaseStatement>MULTIPLE CURRENCIES.<br />DIFFERENT RAILS.<br /><em>ONE ACCOUNT MODEL.</em></CaseStatement><div className="yousewire-wallet">YOUSEWIRE ACCOUNT ↓ CURRENCY WALLETS ↓ BALANCE / ACCOUNT INFORMATION / FUND / SEND / CONVERT</div><div className="yousewire-flow">SELECT CURRENCY ↓ CHECK ELIGIBILITY ↓ VERIFICATION REQUIRED? ↓ VERIFY / CREATE ↓ WALLET ADDED</div><p className="case-pull">COMPLIANCE APPEARS<br />WHEN IT BECOMES RELEVANT.</p><div className="yousewire-flow">ROUTE / DESTINATION ↓ RECIPIENT ↓ AMOUNT + CURRENCY ↓ FEES + EXCHANGE INFORMATION ↓ REVIEW ↓ AUTHENTICATION / CONFIRMATION ↓ PROCESSING ↓ SUCCESS / PENDING / FAILURE</div><CaseMediaPair left={{ index:'04', title:'MULTI-CURRENCY WALLETS' }} right={{ index:'05', title:'SEND MONEY / TRANSFER REVIEW' }} /></CaseAct>
    <CaseAct number="04" title="COMPLIANCE WITHOUT FRICTION" id="yousewire-verification" dark><CaseStatement>COMPLIANCE NEEDED<br />TO BE VISIBLE<br /><em>WITHOUT FEELING HOSTILE.</em></CaseStatement><div className="yousewire-tiers"><section><b>TIER 1</b>CAD 4,500 SINGLE<br />CAD 9,000 / 24 HOURS<br />CAD 40,000 WEEKLY<br />CAD 100,000 MONTHLY</section><section><b>TIER 2</b>CAD 9,000 SINGLE<br />CAD 18,000 / 24 HOURS<br />CAD 50,000 WEEKLY<br />CAD 150,000 MONTHLY</section><section><b>TIER 3</b>CAD 20,000 SINGLE<br />CAD 40,000 / 24 HOURS<br />CAD 150,000 WEEKLY<br />CAD 400,000 MONTHLY</section></div><p className="case-thesis">YOUSEWIRE OWNS THE CONTEXT.<br />THE VERIFICATION PROVIDER OWNS THE VERIFICATION PROCESS.</p><CaseMediaPair left={{ index:'06', title:'VERIFICATION + LIMITS' }} right={{ index:'07', title:'ADDRESS VERIFICATION' }} /></CaseAct>
    <CaseAct number="05" title="FROM WALLET TO OPERATIONS WORKSPACE" id="yousewire-operations"><CaseStatement>A BUSINESS<br />NEEDS MORE<br /><em>THAN A WALLET.</em></CaseStatement><div className="yousewire-operations">BUSINESS CONSOLE ↓ PAY-INS / PAYOUTS / BULK PAYOUTS / BALANCES / DISPUTES / REFERRALS</div><p className="case-body">Bulk payout progression: create batch, choose currency and route, upload or add recipients, validate, resolve invalid rows, review totals, submit, approval, process, review results.</p><p className="case-pull">INVALID ROWS DO NOT HAVE TO<br />BREAK THE ENTIRE MENTAL MODEL.</p><CaseMedia index="08" title="BULK PAYOUT CREATION / VALIDATION / BATCH REVIEW" /><CaseMediaPair left={{ index:'09', title:'PAY-INS + PAYOUTS' }} right={{ index:'10', title:'BALANCES' }} /></CaseAct>
    <CaseAct number="06" title="DESIGNING CONTROL" id="yousewire-control" dark><CaseStatement>MOVING MONEY<br />IS AN ACTION.<br />CONTROLLING WHO CAN MOVE IT<br /><em>IS A SYSTEM.</em></CaseStatement><div className="yousewire-authority">USER ↓ ROLE ↓ PERMISSION ↓ LIMIT ↓ APPROVAL ↓ TRANSACTION ↓ STATE ↓ AUDIT / ACTIVITY</div><div className="yousewire-roles"><section>OWNER<br />ADMIN<br />FINANCE MANAGER<br />APPROVER<br />VIEWER</section><section>CREATE PAYMENTS<br />APPROVE PAYMENTS<br />VIEW REPORTS<br />MANAGE TEAM<br />MANAGE SETTINGS<br />ACCESS SENSITIVE FINANCIAL INFORMATION</section></div><CaseStatement>MONEY DOESN'T<br />JUST SUCCEED<br /><em>OR FAIL.</em></CaseStatement><div className="yousewire-states">EMPTY / LOADING / PENDING / PROCESSING / COMPLETED / FAILED / RESTRICTED / VERIFICATION REQUIRED / UNDER REVIEW / APPROVAL REQUIRED / LIMIT EXCEEDED / PERMISSION DENIED</div><p className="case-thesis">A FINANCIAL STATE SHOULD ANSWER:<br />WHAT HAPPENED? WHAT CAN I DO? DO I NEED TO DO ANYTHING?</p><CaseMediaPair left={{ index:'11', title:'TEAM + ROLES / PERMISSIONS' }} right={{ index:'12', title:'APPROVAL QUEUE / PAYMENT APPROVAL' }} /></CaseAct>
    <CaseAct number="07" title="WHEN THE PRODUCT BECAME AN OPERATING SYSTEM" id="yousewire-settings"><CaseStatement>SETTINGS BECAME<br /><em>A CONTROL CENTER.</em></CaseStatement><div className="yousewire-settings"><section>PERSONAL<br /><small>PROFILE / VERIFICATION + LIMITS / SECURITY / PAYMENT PREFERENCES / NOTIFICATIONS / LINKED ACCOUNTS / DOCUMENTS / REFERRALS / SUPPORT</small></section><section>BUSINESS<br /><small>BUSINESS PROFILE / VERIFICATION + COMPLIANCE / TEAM + ROLES / APPROVAL WORKFLOWS / LIMITS / PAYMENT CONFIGURATION / PAYOUT METHODS / DOCUMENTS / AUDIT / ACTIVITY</small></section></div><CaseStatement>THEN PAYROLL<br />ENTERED<br /><em>THE SYSTEM.</em></CaseStatement><div className="yousewire-payroll">EMPLOYEE ↓ PAY GRADE ↓ EARNINGS + DEDUCTIONS ↓ SALARY COMPONENTS ↓ GROSS MONTHLY PAY ↓ PAYSLIP</div><CaseMediaPair left={{ index:'13', title:'BUSINESS SETTINGS / TEAM SETTINGS' }} right={{ index:'14', title:'PAYROLL / EMPLOYEE PAY CONFIGURATION' }} /></CaseAct>
    <CaseAct number="08" title="COMPLEXITY WHERE IT BELONGS" id="yousewire-reflection" dark><CaseStatement>THE PRODUCT BECAME<br />MORE COMPLEX.<br /><em>THE EXPERIENCE DIDN'T HAVE TO.</em></CaseStatement><div className="yousewire-trust">BEFORE MONEY MOVES: CLEAR SUMMARY / VISIBLE FEES / EXCHANGE INFORMATION / CONFIRMATION<br /><br />WHILE MONEY MOVES: EXPLICIT STATUS / CONSISTENT TERMINOLOGY<br /><br />WHEN SOMETHING CHANGES: RECOVERABLE ERRORS / COMPLIANCE CONTEXT / SECURITY PROMPTS</div><p className="case-body">Designed in Figma, with Product/Project Managers, Developers and Stakeholders around requirements, operational rules, implementation feasibility, edge cases, evolving flows and development handoff.</p><p className="case-closing-thesis">COMPLEX PRODUCTS<br />DO NOT NEED<br />TO FEEL COMPLICATED.</p><a className="yousewire-live" href="https://app.yousewire.com/personal/wallets" target="_blank" rel="noreferrer">VISIT LIVE PRODUCT ↗</a></CaseAct><footer className="yousewire-closing"><div className="section-label">M/ CASE 003 <span>YOUSEWIRE</span></div><h2>COMPLEXITY<br />WHERE IT<br /><em>BELONGS.</em></h2><button onClick={onBack}>← BACK TO WORK</button></footer></article>
}

function HanyaCase({ onBack }: { onBack: () => void }) {
  const [activeAct, setActiveAct] = useState(1)
  useEffect(() => {
    const acts = [...document.querySelectorAll<HTMLElement>('.hanya-case .case-act')]
    const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) setActiveAct(Number((entry.target as HTMLElement).dataset.act ?? 1)) }), { threshold: .35 })
    acts.forEach(act => observer.observe(act)); return () => observer.disconnect()
  }, [])
  return <article className="hanya-case" id="top"><div className="case-progress" aria-label={`Case study progress: act ${activeAct} of 8`}>M/ CASE 002 <span>{String(activeAct).padStart(2, '0')} / 08</span></div><header className="hanya-hero"><div className="section-label">M/ CASE 002 <span>HANYA</span></div><h1>HELPING PEOPLE<br />KNOW WHERE<br />TO GO NEXT.</h1><p>An AI-assisted healthcare navigator that helps people understand what kind of care to seek next, without pretending to diagnose them.</p><dl className="case-metadata"><div><dt>ROLE</dt><dd>Product Designer +<br />Frontend Implementation</dd></div><div><dt>SCOPE</dt><dd>Product strategy<br />UX flows<br />Interaction design<br />Safety architecture<br />UI design<br />Prototyping<br />Frontend implementation</dd></div><div><dt>PLATFORM</dt><dd>Responsive web application</dd></div><div><dt>TOOLS</dt><dd>Figma<br />React<br />TypeScript<br />Vite<br />OpenAI-ready AI layer</dd></div><div><dt>STATUS</dt><dd>Functional MVP</dd></div></dl><CaseMedia index="01" title="HANYA / UNDERSTANDING - PRIMARY PRODUCT VIEW" className="case-hero-media" /></header>
    <CaseAct number="01" title="THE NAVIGATION GAP" id="hanya-navigation-gap"><CaseStatement>PEOPLE DESCRIBE<br />SYMPTOMS.<br /><em>HEALTHCARE SYSTEMS<br />ASK THEM TO CHOOSE SERVICES.</em></CaseStatement><div className="hanya-gap"><section><span>WHAT THE USER KNOWS</span><p>“I have a red, teary eye.”</p></section><i>↓</i><section><span>THE GAP</span><p>“What kind of care do I actually need?”</p></section><i>↓</i><section><span>WHAT HEALTHCARE DIRECTORIES EXPECT</span><p>“Choose a specialty or provider.”</p></section></div><p className="case-thesis">HOW MIGHT WE GUIDE SOMEONE TOWARD APPROPRIATE CARE<br />WITHOUT MAKING HANYA FEEL LIKE A DOCTOR?</p><div className="hanya-constraints">{['NATURAL LANGUAGE FIRST','PROGRESSIVE UNDERSTANDING','SAFETY BEFORE COMPLETION','GUIDANCE, NOT DIAGNOSIS'].map((item,index) => <div key={item}><span>0{index + 1}</span>{item}</div>)}</div></CaseAct>
    <CaseAct number="02" title="THREE DECISIONS" id="hanya-journey" dark><CaseStatement>I REDUCED<br />THE EXPERIENCE<br />TO <em>THREE DECISIONS.</em></CaseStatement><div className="hanya-three"><span>UNDERSTANDING</span><i>↓</i><span>NEXT STEP</span><i>↓</i><span>FIND CARE</span></div><div className="hanya-flow">WELCOME ↓ UNDERSTANDING ↓ FOLLOW-UP ↓ SAFETY CHECK <b>EMERGENCY ESCALATION</b> <span>GUIDANCE ↓ NEXT STEP ↓ FIND CARE ↓ PROVIDER RESULTS ↓ PROVIDER DETAIL</span></div><CaseMedia index="02" title="THREE-STAGE PROGRESS INDICATOR" /></CaseAct>
    <CaseAct number="03" title="DESIGNING UNDERSTANDING" id="hanya-understanding"><CaseStatement>THE CONVERSATION<br />IS STRUCTURED<br />UNDERNEATH,<br /><em>EVEN WHEN IT FEELS NATURAL.</em></CaseStatement><p className="case-body">“I have a red, teary eye and it has been bothering me since yesterday.”</p><div className="hanya-context-flow"><span>NATURAL LANGUAGE</span><i>↓</i><span>STRUCTURED CONTEXT</span><i>↓</i><span>WHAT IS STILL MISSING?</span><i>↓</i><span>NEXT USEFUL QUESTION</span></div><CaseMediaPair left={{ index: '03', title: 'UNDERSTANDING / INITIAL CONCERN' }} right={{ index: '04', title: 'UNDERSTANDING / FOLLOW-UP' }} /><CaseMedia index="05" title="UNDERSTANDING / POPULATED HANYA UNDERSTANDS" /><p className="case-pull">NATURAL LANGUAGE IN<br />→<br />STRUCTURED CONTEXT UNDERNEATH</p></CaseAct>
    <CaseAct number="04" title="THE AI BOUNDARY" id="hanya-ai-boundary" dark><CaseStatement>THE AI WAS<br />NOT ALLOWED<br />TO OWN<br /><em>THE SAFETY DECISION.</em></CaseStatement><p className="case-body">I separated conversational intelligence from healthcare pathway logic.</p><div className="hanya-boundary"><section><span>LAYER 01</span><h3>AI / CONVERSATIONAL LAYER</h3><p>USER LANGUAGE<br />EXTRACTION<br />CONVERSATIONAL RESPONSE</p></section><i>↓</i><section><span>LAYER 02</span><h3>DETERMINISTIC HANYA ENGINE</h3><p>CONTEXT ACCUMULATION<br />SAFETY RULES<br />MISSING FIELDS<br />PATHWAY SELECTION<br />PROVIDER MATCHING</p></section><i>↓</i><section><span>LAYER 03</span><h3>PRODUCT OUTCOME</h3><p>CONTINUE CONVERSATION<br />RECOMMEND NEXT STEP<br />EMERGENCY ESCALATION<br />FIND CARE</p></section></div><p className="case-thesis">THE MODEL ASSISTS INTERPRETATION.<br />THE PRODUCT ENGINE CONTROLS THE HEALTHCARE PATHWAY.</p></CaseAct>
    <CaseAct number="05" title="SAFETY INTERRUPTS THE JOURNEY" id="hanya-safety"><CaseStatement>SAFETY<br />INTERRUPTS<br /><em>THE NORMAL JOURNEY.</em></CaseStatement><div className="hanya-interrupt"><span>ROUTINE CONTEXT<br /><b>CONTINUE NAVIGATOR</b></span><span>POTENTIAL EMERGENCY PATTERN<br /><b>INTERRUPT FLOW<br />↓<br />EMERGENCY ACTION</b></span></div><CaseMedia index="06" title="EMERGENCY / PLEASE SEEK EMERGENCY CARE NOW" /><p className="case-body">The experience gives clear instruction to seek emergency care with an emergency call action and concise supporting language. Hanya cannot determine or rule out a medical emergency, so provider browsing is deliberately removed.</p><p className="case-pull">WHEN SAFETY BECOMES THE PRIORITY,<br />SECONDARY DECISIONS DISAPPEAR.</p></CaseAct>
    <CaseAct number="06" title="FROM GUIDANCE TO CARE" id="hanya-guidance" dark><CaseStatement>HANYA GIVES<br />DIRECTION<br /><em>WITHOUT PRESENTING<br />A DIAGNOSIS.</em></CaseStatement><p className="case-body">“Starting with a primary care clinician would be a reasonable next step. They can assess what you're experiencing and refer you if needed.”</p><div className="hanya-actions"><span>01<br />FIND PRIMARY CARE</span><span>02<br />LEARN MORE</span></div><CaseMedia index="07" title="GUIDANCE / BASED ON WHAT YOU'VE SHARED" /><CaseStatement>PROVIDER SEARCH<br />BEGINS WITH CONTEXT<br />THE USER HAS<br /><em>ALREADY GIVEN.</em></CaseStatement><p className="case-body">Recommended care type, location, availability, consultation cost, insurance compatibility and match reason carry into Find Care. Guidance becomes an actionable provider choice.</p><CaseMediaPair left={{ index: '08', title: 'FIND CARE / RESULTS' }} right={{ index: '09', title: 'PROVIDER DETAIL / SUNRISE CLINIC IKEJA' }} /></CaseAct>
    <CaseAct number="07" title="BUILDING THE SYSTEM" id="hanya-system"><CaseStatement>THE PRODUCT<br />STILL NEEDED<br />TO WORK<br /><em>BEFORE LIVE AI USAGE.</em></CaseStatement><div className="hanya-fallback"><section><span>MOCK / FALLBACK MODE</span><p>Pattern-based extraction<br />Same context structure<br />Same safety engine<br />Same pathway logic<br />No paid API required</p></section><section><span>OPENAI-READY MODE</span><p>Model-assisted extraction<br />Same context structure<br />Same safety engine<br />Same pathway logic<br />API configuration required</p></section></div><p className="case-thesis">DIFFERENT INTERPRETATION LAYER.<br />SAME SAFETY AND NAVIGATION ARCHITECTURE.</p><div className="hanya-tests"><span><b>263</b>TESTS PASSING</span><span><b>13</b>TEST FILES</span><span><b>TYPESCRIPT</b>CLEAN</span><span><b>PRODUCTION BUILD</b>PASSING</span></div><div className="hanya-iterations">{[['REPEATING CONVERSATION','CONTEXT-AWARE PROGRESSION'],['DEAD “VIEW DETAILS” ACTION','PROVIDER DETAIL STATE'],['STATIC HANYA LOGO','PERSISTENT HOME NAVIGATION'],['EMERGENCY PROVIDER BROWSING','FOCUSED EMERGENCY ESCALATION']].map(([before, after], index) => <div key={before}><span>0{index + 1}</span><p>{before}<b>→</b>{after}</p></div>)}</div><p className="case-pull">A HEALTHCARE NAVIGATION EXPERIENCE SHOULD REDUCE DECISIONS<br />AT THE MOMENTS WHEN USERS HAVE THE LEAST CAPACITY TO MAKE THEM.</p></CaseAct>
    <CaseAct number="08" title="THE NEXT DECISION" id="hanya-reflection" dark><CaseStatement>ONE CONVERSATION.<br />ONE CLEARER<br /><em>NEXT STEP.</em></CaseStatement><div className="hanya-final-flow">DESCRIBE WHAT IS HAPPENING ↓ CLARIFY THE CONCERN ↓ EVALUATE SAFETY ↓ RECOMMEND A NEXT STEP ↓ FIND RELEVANT CARE</div><CaseMedia index="10" title="FINAL NAVIGATOR JOURNEY / WELCOME TO PROVIDER DETAIL" /><div className="hanya-reflection">WHAT SHOULD THE MODEL BE RESPONSIBLE FOR?<br /><br />WHICH DECISIONS NEED DETERMINISTIC CONTROL?<br /><br />HOW DO I SHOW USERS WHAT THE SYSTEM UNDERSTANDS?<br /><br />WHAT HAPPENS WHEN THE AI SERVICE IS UNAVAILABLE?</div><p className="case-closing-thesis">THE AI IS NOT THE INTERFACE.<br />THE USER'S NEXT DECISION IS.</p><div className="hanya-outcome"><span>FUNCTIONAL RESPONSIVE MVP</span><p>natural-language healthcare intake<br />multi-turn context accumulation<br />structured understanding<br />deterministic emergency escalation<br />care-pathway guidance<br />provider discovery and detail views<br />insurance-aware provider information<br />mock/fallback operation<br />OpenAI-ready service boundary<br />automated regression coverage<br />production deployment</p></div></CaseAct>
    <footer className="hanya-closing"><div className="section-label">M/ CASE 002 <span>HANYA</span></div><h2>GUIDANCE FOR<br />THE <em>NEXT DECISION.</em></h2><p>An AI-assisted healthcare navigation MVP built around guidance, safety and human judgement.</p><button onClick={onBack}>← BACK TO WORK</button></footer></article>
}

function PrimaCase({ onBack }: { onBack: () => void }) {
  const [activeLayer, setActiveLayer] = useState('CREDENTIAL')
  const [activeAct, setActiveAct] = useState(1)
  const layers = ['CUSTOMER DID', 'CREDENTIAL', 'ISSUER', 'CRYPTOGRAPHIC PROOF', 'CREDENTIAL STATUS', 'MERCHANT POLICY', 'PAYMENT AUTHORIZATION', 'SETTLEMENT']
  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const acts = [...document.querySelectorAll<HTMLElement>('.prima-case .case-act')]
    const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) setActiveAct(Number((entry.target as HTMLElement).dataset.act ?? 1)) }), { threshold: .35 })
    acts.forEach(act => observer.observe(act))
    return () => observer.disconnect()
  }, [])
  return <article className="prima-case" id="top"><div className="case-progress" aria-label={`Case study progress: act ${activeAct} of 7`}>M/ CASE 001 <span>{String(activeAct).padStart(2, '0')} / 07</span></div><header className="prima-hero"><div className="section-label">M/ CASE 001 <span>PRIMA</span></div><h1>DESIGNING TRUST<br />FOR PAYMENTS WITHOUT<br />TRADITIONAL<br />PAYMENT RAILS.</h1><p>Prima is an AI-assisted verification operating system that helps merchants verify decentralized identities and credentials, investigate suspicious transactions, and make informed settlement decisions.</p><dl className="case-metadata"><div><dt>ROLE</dt><dd>Product Designer</dd></div><div><dt>SCOPE</dt><dd>Product Strategy<br />UX/UI Design<br />AI Experience<br />Prototyping</dd></div><div><dt>PLATFORM</dt><dd>Merchant Web Application</dd></div><div><dt>PROJECT TYPE</dt><dd>Speculative Product Concept</dd></div><div><dt>PROTOTYPE</dt><dd>Interactive Frontend</dd></div></dl><CaseMedia index="01" title="OPERATIONS DASHBOARD" className="case-hero-media" /></header>
    <CaseAct number="01" title="THE PREMISE" id="prima-premise"><CaseStatement>WHAT HAPPENS TO MERCHANT TRUST<br />WHEN THE PAYMENT RAILS<br />WE RELY ON DISAPPEAR?</CaseStatement><p className="case-body">Prima explores a future shaped by decentralized identity, Verifiable Credentials, digital currencies and wallet-authorized payments, where traditional card infrastructure is no longer the default. The core merchant question became: <strong>CAN I TRUST THIS TRANSACTION ENOUGH TO ACCEPT IT?</strong></p></CaseAct>
    <CaseAct number="02" title="THE TRUST PROBLEM" id="prima-trust-problem" dark><CaseStatement>VERIFICATION WAS HAPPENING.<br /><em>UNDERSTANDING WASN'T.</em></CaseStatement><p className="case-body">A decentralized payment can fail because a credential expired, a cryptographic proof is invalid, an issuer is unavailable, a credential was revoked, a presentation was replayed, or transaction behaviour is unusual. The question is not simply failed. It is what exactly failed, and what should I do next?</p><p className="case-pull">THE SYSTEM KNEW WHAT FAILED.<br />THE HUMAN DIDN'T.</p><div className="verification-architecture" aria-label="Verification architecture. Customer DID, credential, issuer, cryptographic proof, credential status, merchant policy, payment authorization, settlement.">{layers.map(layer => <button className={activeLayer === layer ? 'is-active' : ''} onClick={() => setActiveLayer(layer)} key={layer}><span>{layer}</span><small>{activeLayer === layer ? layer === 'SETTLEMENT' ? 'FINAL SYSTEM STATE' : 'INDEPENDENT CHECK' : ''}</small></button>)}</div><p className="case-body">The challenge was not to hide complexity completely. It was to decide how much of it each person needed to see, and when. Cashier, operator and investigator each require a different level of evidence.</p></CaseAct>
    <CaseAct number="03" title="THE AI DECISION" id="prima-ai-boundary"><CaseStatement>I SEPARATED<br />VERIFICATION FROM<br /><em>interpretation.</em></CaseStatement><p className="case-body">If AI determined whether cryptographic evidence was valid, the most important trust decision would become probabilistic. I deliberately rejected that architecture.</p><div className="case-comparison"><section><span>DETERMINISTIC<br />VERIFICATION</span><h3>ESTABLISHES:<br />WHAT THE EVIDENCE SAYS</h3><p>DID Resolution<br />Credential Proof<br />Issuer Information<br />Credential Status<br />Merchant Policy<br />Payment Authorization</p><b>VERIFIED<br />FAILED<br />INDETERMINATE</b></section><section><span>AI-ASSISTED<br />INVESTIGATION</span><h3>HELPS HUMANS UNDERSTAND:<br />WHAT THE EVIDENCE MEANS</h3><p>Failure Explanation<br />Evidence Correlation<br />Probable Causes<br />Anomaly Interpretation<br />Recommended Actions</p><b>ANALYSIS<br />EVIDENCE<br />RECOMMENDATION</b></section></div><p className="case-thesis">AI CAN INTERPRET THE EVIDENCE.<br />IT CANNOT CHANGE WHAT THE EVIDENCE SAYS.</p></CaseAct>
    <CaseAct number="04" title="MAKING FAILURE VISIBLE" id="prima-replay" dark><CaseStatement>MAKE VERIFICATION<br /><em>OBSERVABLE.</em></CaseStatement><p className="case-body">The Verify experience exposes enough of the verification pipeline to make the eventual answer understandable. Verification succeeds first. Settlement still requires merchant authorization.</p><CaseMediaPair left={{ index: '02', title: 'VERIFY - PIPELINE' }} right={{ index: '03', title: 'IDENTITY VERIFIED / MERCHANT AUTHORIZATION' }} /><CaseStatement>A FAILED PAYMENT<br />WASN'T ENOUGH.<br />I NEEDED TO SHOW<br />WHERE IT FAILED.</CaseStatement><p className="case-body">Verification Replay reconstructs verification chronologically and identifies the exact point where the trust chain broke.</p><div className="replay-state"><span>DID<br /><b>PASSED</b></span><span>CREDENTIAL<br /><b>PASSED</b></span><span>ISSUER<br /><b>PASSED</b></span><span>CRYPTOGRAPHIC PROOF<br /><b>FAILED</b></span><span>SETTLEMENT<br /><b>HALTED</b></span></div><CaseMedia index="04" title="VERIFICATION REPLAY" caption="WHAT PASSED: DID, credential and issuer resolved successfully. WHERE IT FAILED: cryptographic proof verification. WHAT HAPPENED NEXT: settlement authorization halted." /><p className="case-pull">AN OPAQUE SYSTEM ERROR<br />BECAME AN INSPECTABLE EVENT.</p><div id="prima-evidence"><CaseStatement>EVIDENCE FIRST.<br /><em>EXPLANATION SECOND.</em></CaseStatement><CaseMediaPair left={{ index: '05', title: 'VERIFICATION DETAILS' }} right={{ index: '06', title: 'CREDENTIAL TRUST CHAIN' }} /><p className="case-body">Progressive disclosure keeps Verification Result, Cryptographic Proof, Credential Status, Issuer Status, Merchant Policy, Investigation Status and Settlement Status separate.</p></div><div id="prima-investigator"><CaseStatement>AI EXPLAINS<br />THE EVIDENCE.<br />IT DOESN'T DECIDE<br />THE <em>truth.</em></CaseStatement><CaseMedia index="07" title="AI INVESTIGATOR - CRYPTOGRAPHIC MISMATCH" /><p className="case-body">AI Investigator presents incident analysis, evidence, probable causes, recommended action and AI analysis confidence. That confidence describes Prima's interpretation of the incident, not confidence in the validity of cryptographic evidence.</p></div></CaseAct>
    <CaseAct number="05" title="DESIGNING FOR UNCERTAINTY" id="prima-human-control"><CaseStatement>HUMAN DECISIONS<br /><em>REMAIN VISIBLE.</em></CaseStatement><div className="state-separation"><section><span>FAILED PATH</span><p>VERIFICATION<br /><b>FAILED</b><i>↓</i>INVESTIGATION<br /><b>ESCALATED</b><i>↓</i>SETTLEMENT<br /><b>BLOCKED</b></p></section><section><span>SUCCESSFUL PATH</span><p>VERIFICATION<br /><b>VERIFIED</b><i>↓</i>MERCHANT AUTHORIZATION<i>↓</i>SETTLEMENT<br /><b>CONFIRMED</b></p></section></div><p className="case-thesis">ESCALATING AN INVESTIGATION<br />DOESN'T REWRITE THE VERIFICATION RESULT.</p><div className="knowledge-comparison" id="prima-uncertainty"><section><span>FAILED</span><h3>Cryptographic proof invalid.</h3><p><b>SYSTEM KNOWLEDGE:</b> Enough evidence exists to reject verification.</p><strong>SETTLEMENT BLOCKED.</strong></section><section><span>INDETERMINATE</span><h3>Issuer service unavailable.</h3><p><b>SYSTEM KNOWLEDGE:</b> Prima cannot currently establish validity.</p><strong>TRANSACTION HELD FOR REVIEW.</strong></section></div><p className="case-pull">NOT EVERY FAILURE<br />MEANS THE SAME THING.</p></CaseAct>
    <CaseAct number="06" title="FROM SCREEN TO SYSTEM" id="prima-operating-system" dark><CaseStatement>VERIFICATION<br />WASN'T A SCREEN.<br />IT BECAME AN<br /><em>OPERATING SYSTEM.</em></CaseStatement><p className="case-body">The concept expanded into Operations, Alerts, Trust Policies and Integrations.</p><CaseMedia index="08" title="OPERATIONS" /><CaseMediaPair left={{ index: '09', title: 'ALERTS' }} right={{ index: '10', title: 'TRUST POLICIES' }} /><section className="merchant-authority" id="prima-merchant-authority"><CaseStatement>MERCHANT CONTROL<br />STOPS AT THE MERCHANT.</CaseStatement><p className="case-body">A merchant can stop accepting credentials from an issuer. The merchant cannot revoke that issuer globally. Prima can restrict a DID inside the merchant environment or add it to a watchlist. It cannot globally block someone's decentralized identity.</p><p className="case-thesis">PRIMA MANAGES MERCHANT ACCEPTANCE POLICY.<br />NOT THE DECENTRALIZED ECOSYSTEM ITSELF.</p></section><div className="scenario-matrix" id="prima-scenarios">{[['✓','CLEAN VERIFICATION','SUCCESSFUL VERIFICATION'],['✕','CRYPTOGRAPHIC PROOF MISMATCH','INVALID EVIDENCE'],['✕','REVOKED CREDENTIAL','CREDENTIAL STATUS'],['✕','EXPIRED CREDENTIAL','CREDENTIAL VALIDITY'],['?','DID SERVICE UNAVAILABLE','INFRASTRUCTURE UNCERTAINTY'],['?','ISSUER SERVICE UNAVAILABLE','INFRASTRUCTURE UNCERTAINTY'],['⚠','DUPLICATE PRESENTATION / REPLAY','SECURITY ANOMALY'],['⚠','HIGH-VALUE ANOMALY','BEHAVIOURAL ANOMALY']].map(([state, title, description]) => <div key={title}><b>{state}</b><strong>{title}</strong><small>{description}</small></div>)}</div><CaseStatement>THE SCREENS NEEDED<br />TO BEHAVE LIKE<br /><em>ONE SYSTEM.</em></CaseStatement><div className="connected-system" aria-label="Connected product architecture"><span>OPERATIONS</span><span>VERIFY</span><span>VERIFICATION TIMELINE</span><span>TRUST CHAIN</span><span>VERIFICATION REPLAY</span><span>AI INVESTIGATION</span><span>ALERTS</span><span>TRUST POLICIES</span><span>SETTLEMENT</span></div><p className="case-pull">I BUILT ENOUGH OF PRIMA<br />TO TEST THE PRODUCT LOGIC,<br />NOT JUST THE SCREENS.</p><section className="prototype-disclosure" id="prima-prototype"><span>M/ PROTOTYPE</span><h3>CONNECTED FRONTEND PROTOTYPE</h3><div><p><b>SIMULATES:</b><br />deterministic verification scenarios<br />shared application state<br />connected operational behaviour</p><p><b>DOES NOT INCLUDE:</b><br />real authentication<br />real DID resolution<br />real VC verification<br />real AI calls<br />real payment settlement<br />real blockchain/network connections<br />production backend infrastructure</p></div><button disabled>VIEW LIVE PROTOTYPE / PENDING</button></section></CaseAct>
    <CaseAct number="07" title="WHAT CHANGED IN MY THINKING" id="prima-reflection"><div className="section-label">M/ REFLECTION <span>WHAT I LEARNED</span></div><CaseStatement>EXPLAINABILITY<br />ISN'T THE SAME AS<br /><em>simplification.</em></CaseStatement><p className="case-body">For high-stakes systems, the better experience is not always to remove complexity. Sometimes it is to reveal the right complexity at the right moment. Designing AI responsibly can mean deliberately reducing its authority.</p><div className="case-support-media"><CaseMediaPair left={{ index: '11', title: 'AI INVESTIGATOR - ESCALATED' }} right={{ index: '12', title: 'AI INVESTIGATOR - DEGRADED ISSUER / HIGH-VALUE ANOMALY' }} /><CaseMediaPair left={{ index: '13', title: 'TRUST POLICIES - PAUSED' }} right={{ index: '14', title: 'INTEGRATIONS' }} /></div><p className="case-closing-thesis">RESPONSIBLE AI DESIGN<br />CAN SOMETIMES MEAN<br />DELIBERATELY GIVING AI<br />LESS AUTHORITY.</p></CaseAct>
    <footer className="prima-closing"><div className="section-label">M/ CASE 001 <span>PRIMA</span></div><h2>MAKING MACHINE TRUST<br />UNDERSTANDABLE TO<br /><em>humans.</em></h2><p>A speculative exploration of decentralized payments, explainable verification and human-centered AI.</p><button onClick={onBack}>← MORE WORK</button><span>NEXT CASE<br />NOMI</span></footer>
  </article>
}

function CaseAct({ number, title, id, dark = false, children }: { number: string; title: string; id: string; dark?: boolean; children: React.ReactNode }) { return <section className={`case-act ${dark ? 'case-act-dark' : ''}`} id={id} data-act={number}><div className="case-act-label">ACT {number}<span>{title}</span></div>{children}</section> }
function CaseStatement({ children }: { children: React.ReactNode }) { return <h2 className="case-statement">{children}</h2> }

function Lab({ onExperimentOpen }: { onExperimentOpen: (slug: string) => void }) { return <section className="lab-page" id="lab"><div className="section-label">M/LAB <span>INDEX</span></div><h1>SMALL THINGS<br />BUILT TO ANSWER<br /><em>interesting questions.</em></h1><p className="lab-intro">A collection of small experiments I use to explore how AI changes the way we design, build and interact with software.</p>{labExperiments.length ? <div className="lab-experiment-index">{labExperiments.map(experiment => <button onClick={() => onExperimentOpen(experiment.slug)} key={experiment.id}><span>M/LAB {experiment.id}</span><h2>{experiment.title}</h2><small>{experiment.status}</small></button>)}</div> : <div className="lab-empty"><span>M/ CURRENT STATE</span><h2>EXPERIMENTS<br />IN PROGRESS.</h2><p>New things will appear here as I build them.</p></div>}</section> }

function LabExperimentPage({ experiment, onBack }: { experiment?: LabExperiment; onBack: () => void }) {
  if (!experiment) return <section className="lab-experiment-empty" id="top"><div className="section-label">M/LAB <span>EXPERIMENT</span></div><h1>EXPERIMENT<br /><em>IN PREPARATION.</em></h1><p>This experiment is not indexed yet.</p><button onClick={onBack}>← BACK TO M/LAB</button></section>
  const Artifact = experiment.Artifact
  return <article className="lab-experiment" id="top"><header><div className="section-label">M/LAB {experiment.id} <span>{experiment.category} / {experiment.year}</span></div><h1>{experiment.title}</h1></header><section><div className="section-label">M/ QUESTION <span>01</span></div><h2>{experiment.question}</h2></section><section><div className="section-label">M/ EXPERIMENT <span>02</span></div><p>{experiment.experiment}</p></section><section className="lab-thing"><div className="section-label">M/ THE THING <span>03</span></div>{Artifact ? <Artifact /> : <div className="lab-media-placeholder">MEDIA / ARTIFACT TO BE ADDED</div>}</section><section><div className="section-label">M/ WHAT I LEARNED <span>04</span></div><ul>{experiment.learning.map(item => <li key={item}>{item}</li>)}</ul></section><section><div className="section-label">M/ BUILT WITH <span>05</span></div><p className="lab-tools">{experiment.tools.join(' / ')}</p></section><footer><button onClick={onBack}>BACK TO M/LAB</button></footer></article>
}

function GlobalFooter() { return <footer className="global-footer"><span>M/ CONTACT</span><div><a href={`mailto:${contact.email}`} aria-label={`Email Malik at ${contact.email}`}>EMAIL ↗</a><a href={contact.linkedin} target="_blank" rel="noreferrer" aria-label="Visit Malik's LinkedIn profile, opens in a new tab">LINKEDIN ↗</a></div></footer> }

function Contact() { return <section className="contact section" id="contact"><div className="section-label">M/ CONTACT <span>05</span></div><h2>HAVE A<br />COMPLICATED<br />PROBLEM?</h2><em>Good.</em><a className="talk" href={`mailto:${contact.email}`} aria-label={`Email Malik at ${contact.email}`}>LET'S TALK <span>↗</span></a><div className="contact-links"><a href={`mailto:${contact.email}`} aria-label={`Email Malik at ${contact.email}`}>EMAIL ↗</a><a href={contact.linkedin} target="_blank" rel="noreferrer" aria-label="Visit Malik's LinkedIn profile, opens in a new tab">LINKEDIN ↗</a></div><div className="contact-meta"><span>{contact.email}</span><span>LAGOS, NG</span><span>GLOBAL / REMOTE</span><span>AVAILABLE FOR SELECTED COLLABORATIONS</span></div></section> }
createRoot(document.getElementById('root')!).render(<App />)
